package com.bank.qa.uidb;

import java.math.BigDecimal;
import java.time.LocalDate;

// A normalized, comparable record keyed by transaction id.
class Row {
    final String id;
    final String name;      // normalized case
    final BigDecimal amount;// money as BigDecimal, scale 2
    final LocalDate date;   // canonical date
    Row(String id, String name, BigDecimal amount, LocalDate date) {
        this.id = id; this.name = name; this.amount = amount; this.date = date;
    }
    @Override public boolean equals(Object o) {
        if (!(o instanceof Row)) return false;
        Row r = (Row) o;
        return id.equals(r.id) && name.equals(r.name)
            && amount.compareTo(r.amount) == 0 && date.equals(r.date);
    }
    @Override public int hashCode() { return id.hashCode(); }
    @Override public String toString() {
        return "{" + id + ", " + name + ", " + amount + ", " + date + "}";
    }
}
