package com.bank.qa.uidb;

import java.util.*;
import java.util.logging.Logger;

// Compares keyed sets of rows and reports precise mismatches.
class UiDbComparator {
    private static final Logger log = Logger.getLogger(UiDbComparator.class.getName());

    boolean compare(List<Row> uiRows, List<Row> dbRows) {
        Map<String, Row> ui = index(uiRows);
        Map<String, Row> db = index(dbRows);
        boolean allMatch = true;

        // Keyed comparison avoids pagination/order false mismatches.
        for (String id : db.keySet()) {
            Row d = db.get(id), u = ui.get(id);
            if (u == null) {
                log.severe("MISSING in UI: id=" + id + " db=" + d);
                allMatch = false;
            } else if (!u.equals(d)) {
                log.severe("MISMATCH id=" + id + " ui=" + u + " db=" + d);
                allMatch = false;
            } else {
                log.info("MATCH id=" + id);
            }
        }
        for (String id : ui.keySet()) {
            if (!db.containsKey(id)) {
                log.severe("EXTRA in UI (not in DB): id=" + id + " ui=" + ui.get(id));
                allMatch = false;
            }
        }
        return allMatch;
    }

    private Map<String, Row> index(List<Row> rows) {
        Map<String, Row> m = new LinkedHashMap<>();
        for (Row r : rows) m.put(r.id, r);
        return m;
    }
}
