package com.bank.qa.uidb;

import java.util.List;
import java.util.logging.*;

public class UiDbValidationDemo {
    private static final Logger log = Logger.getLogger(UiDbValidationDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new UiDbLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        DataNormalizer n = new DataNormalizer();

        // UI shows grouped currency, "30 Oct 2026", title-cased name, page 1 only
        List<Row> uiRows = List.of(
            new Row("TXN-1", n.name("Rajesh Kumar"), n.money("9,50,000.00"), n.date("30 Oct 2026", "dd MMM yyyy")),
            new Row("TXN-2", n.name("Priya Sharma"), n.money("Rs 50000"),    n.date("29 Oct 2026", "dd MMM yyyy"))
        );

        // DB source of truth: plain decimals, ISO dates, upper-case names
        List<Row> dbRows = List.of(
            new Row("TXN-1", n.name("RAJESH KUMAR"), n.money("950000"),   n.date("2026-10-30", "yyyy-MM-dd")),
            new Row("TXN-2", n.name("PRIYA SHARMA"), n.money("50000.00"), n.date("2026-10-29", "yyyy-MM-dd"))
        );

        log.info("=== UI vs DB comparison (normalized) ===");
        boolean ok = new UiDbComparator().compare(uiRows, dbRows);
        log.info("Overall: " + (ok ? "ALL MATCH (UI reflects source of truth)" : "MISMATCHES FOUND"));

        // Demonstrate a real mismatch being caught (wrong amount on UI)
        log.info("=== Negative: UI shows wrong amount ===");
        List<Row> wrongUi = List.of(
            new Row("TXN-1", n.name("Rajesh Kumar"), n.money("9,50,000.00"), n.date("30 Oct 2026", "dd MMM yyyy")),
            new Row("TXN-2", n.name("Priya Sharma"), n.money("55000"),       n.date("29 Oct 2026", "dd MMM yyyy"))
        );
        new UiDbComparator().compare(wrongUi, dbRows);
    }
}

